const input = $json.body ?? {};
if ($json.headers?.['x-sage-google-action-token'] !== $env.SAGE_GOOGLE_ACTION_TOKEN) throw new Error('Unauthorized Google action request');
const action = String(input.action ?? '');
if (!['CREATE_DRAFT','SEND_DRAFT'].includes(action)) throw new Error('Unsupported Gmail action');
let requestUrl = 'https://gmail.googleapis.com/gmail/v1/users/me/drafts';
let requestBody = {};
if (action === 'CREATE_DRAFT') {
  const recipients = Array.isArray(input.to) ? input.to : [];
  const subject = String(input.subject ?? '');
  const body = String(input.body ?? '');
  if (!recipients.length || recipients.length > 20 || recipients.some(value => !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(String(value)))) throw new Error('Invalid Gmail recipients');
  if (subject.length > 2000 || /[\\r\\n]/.test(subject)) throw new Error('Invalid Gmail subject');
  if (!body || body.length > 50000) throw new Error('Invalid Gmail body');
  const messageId = String(input.messageId ?? '');
  if (!/^[a-f0-9]{32,64}$/.test(messageId)) throw new Error('Invalid Gmail idempotency message ID');
  const rawMessage = [`To: ${recipients.join(', ')}`, `Subject: ${subject}`, `Message-ID: <${messageId}@sage.local>`, 'MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8', '', body].join('\\r\\n');
  requestBody = {message:{raw:Buffer.from(rawMessage,'utf8').toString('base64url')}};
} else {
  const draftId = String(input.draftId ?? '');
  if (!draftId || draftId.length > 1000) throw new Error('Invalid Gmail draft ID');
  requestUrl += '/send';
  requestBody = {id:draftId};
}
return [{json:{action,requestMethod:'POST',requestUrl,requestBody,shouldSendBody:true}}];

