const input = $json.body ?? {};
if ($json.headers?.['x-sage-google-action-token'] !== $env.SAGE_GOOGLE_ACTION_TOKEN) throw new Error('Unauthorized Google action request');
const action = String(input.action ?? '');
if (!['CREATE_CALENDAR_EVENT','UPDATE_CALENDAR_EVENT','DELETE_CALENDAR_EVENT'].includes(action)) throw new Error('Unsupported Calendar action');
const eventId = String(input.eventId ?? '');
if (!eventId || eventId.length > 1000 || /[\\r\\n]/.test(eventId)) throw new Error('Invalid Calendar event ID');
const encodedEventId = encodeURIComponent(eventId);
const requestMethod = {CREATE_CALENDAR_EVENT:'PUT',UPDATE_CALENDAR_EVENT:'PATCH',DELETE_CALENDAR_EVENT:'DELETE'}[action];
const requestUrl = `https://www.googleapis.com/calendar/v3/calendars/primary/events/${encodedEventId}?sendUpdates=all`;
let requestBody = {};
if (action !== 'DELETE_CALENDAR_EVENT') {
  const allowedFields = ['summary','description','location'];
  for (const field of allowedFields) if (input[field] !== undefined) requestBody[field] = String(input[field]);
  if (input.startAt !== undefined) requestBody.start = {dateTime:String(input.startAt)};
  if (input.endAt !== undefined) requestBody.end = {dateTime:String(input.endAt)};
  if (action === 'CREATE_CALENDAR_EVENT' && (!requestBody.summary || !requestBody.start || !requestBody.end)) throw new Error('Incomplete Calendar event');
  if (action === 'UPDATE_CALENDAR_EVENT' && Object.keys(requestBody).length === 0) throw new Error('Empty Calendar update');
}
return [{json:{action,requestMethod,requestUrl,requestBody,shouldSendBody:action !== 'DELETE_CALENDAR_EVENT'}}];
